// flint-render — server-side chart PNG renderer for InsForge (Deno).
// Pipeline: ChartAssemblyInput -> flint-chart assembleECharts -> ECharts SVG (SSR)
//           -> resvg-wasm rasterize -> PNG. For email / API surfaces that can't run
//           the browser-side Flint widget.
//
// Heavy deps are loaded from esm.sh as single bundled modules (InsForge's deploy
// validator rejects an inlined echarts bundle: it does a global no-redeclare scan
// that flags echarts' cross-scope identifier reuse). Fonts are embedded as base64
// string constants (strings don't trip the validator); resvg wasm is fetched once.
import { assembleECharts } from 'https://esm.sh/flint-chart@0.2.2?bundle&target=denonext';
import * as echarts from 'https://esm.sh/echarts@6.1.0?bundle&target=denonext';
import { Resvg, initWasm } from 'https://esm.sh/@resvg/resvg-wasm@2.6.2?bundle&target=denonext';
const FONT_REGULAR_B64 = "";
const FONT_BOLD_B64 = "";

const PROJECT_BASE = Deno.env.get('INSFORGE_BASE_URL');
if (!PROJECT_BASE) throw new Error('INSFORGE_BASE_URL is not configured');
const RESVG_WASM_URL = 'https://cdn.jsdelivr.net/npm/@resvg/resvg-wasm@2.6.2/index_bg.wasm';

function base64ToBytes(base64) {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index++) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

const FONT_BUFFERS = [base64ToBytes(FONT_REGULAR_B64), base64ToBytes(FONT_BOLD_B64)];

// One-time wasm init cached at module scope (inert wasm module; safe to reuse).
let wasmInitPromise = null;
function ensureWasmReady() {
  if (!wasmInitPromise) {
    wasmInitPromise = initWasm(fetch(RESVG_WASM_URL)).catch((error) => {
      wasmInitPromise = null; // let the next request retry a failed cold-start fetch
      throw error;
    });
  }
  return wasmInitPromise;
}

async function runSql(query, params = []) {
  const response = await fetch(`${PROJECT_BASE}/api/database/advance/rawsql`, {
    method: 'POST',
    headers: { 'x-api-key': Deno.env.get('API_KEY'), 'Content-Type': 'application/json' },
    body: JSON.stringify({ query, params }),
  });
  if (!response.ok) throw new Error(`sql ${response.status}: ${await response.text()}`);
  return (await response.json()).rows;
}

function decodeSpecParam(encoded) {
  let normalized = encoded.replace(/-/g, '+').replace(/_/g, '/');
  while (normalized.length % 4) normalized += '=';
  const binary = atob(normalized);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index++) bytes[index] = binary.charCodeAt(index);
  return JSON.parse(new TextDecoder().decode(bytes));
}

// Some agents emit spec values as double-quoted JSON strings, e.g.
// encodings: {"x": "\"site_name\""} or semantic_types: {"value": "\"Quantity\""}.
// Flint then matches no field and the chart renders blank with literally-quoted
// labels. Strip one layer of wrapping double quotes from encoding fields,
// semantic_types values, and chartType. Data rows are left untouched.
function unwrapQuotedString(value) {
  if (typeof value !== 'string') return value;
  const trimmed = value.trim();
  const match = trimmed.match(/^"(.*)"$/s);
  return match ? match[1] : trimmed;
}

function normalizeEncodingValue(value) {
  if (typeof value === 'string') return unwrapQuotedString(value);
  if (value && typeof value === 'object' && typeof value.field === 'string') {
    return { ...value, field: unwrapQuotedString(value.field) };
  }
  return value;
}

// Runtype FPO templates forbid body templates in external tools, so tool params
// auto-serialize as the raw JSON body — a FLAT shape:
//   {title?, chartType, encodings, semanticTypes, rows}
// Assemble it into the nested ChartAssemblyInput the renderer expects. The nested
// {title, input} shape is left untouched.
function assembleFlatBody(body) {
  return {
    data: { values: body.rows },
    semantic_types: body.semanticTypes ?? {},
    chart_spec: {
      chartType: body.chartType,
      encodings: body.encodings ?? {},
      baseSize: { width: 900, height: 500 },
    },
  };
}

function normalizeChartInput(chartInput) {
  if (!chartInput || typeof chartInput !== 'object') return chartInput;
  const normalized = { ...chartInput };

  if (chartInput.semantic_types && typeof chartInput.semantic_types === 'object') {
    const semanticTypes = {};
    for (const [key, value] of Object.entries(chartInput.semantic_types)) {
      semanticTypes[key] = unwrapQuotedString(value);
    }
    normalized.semantic_types = semanticTypes;
  }

  if (chartInput.chart_spec && typeof chartInput.chart_spec === 'object') {
    const chartSpec = { ...chartInput.chart_spec };
    if (typeof chartSpec.chartType === 'string') {
      chartSpec.chartType = unwrapQuotedString(chartSpec.chartType);
    }
    if (chartSpec.encodings && typeof chartSpec.encodings === 'object') {
      const encodings = {};
      for (const [channel, value] of Object.entries(chartSpec.encodings)) {
        encodings[channel] = normalizeEncodingValue(value);
      }
      chartSpec.encodings = encodings;
    }
    normalized.chart_spec = chartSpec;
  }

  return normalized;
}

function renderChartPng(rawChartInput) {
  const chartInput = normalizeChartInput(rawChartInput);
  const chartWidth = chartInput?.chart_spec?.baseSize?.width ?? 900;
  const chartHeight = chartInput?.chart_spec?.baseSize?.height ?? 500;
  const option = assembleECharts(chartInput);
  const chart = echarts.init(null, null, { renderer: 'svg', ssr: true, width: chartWidth, height: chartHeight });
  chart.setOption(option);
  const svg = chart.renderToSVGString();
  chart.dispose();
  const resvg = new Resvg(svg, {
    background: '#ffffff',
    fitTo: { mode: 'width', value: chartWidth },
    font: {
      fontBuffers: FONT_BUFFERS,
      defaultFontFamily: 'Inter',
      loadSystemFonts: false,
      serifFamily: 'Inter',
      sansSerifFamily: 'Inter',
      cursiveFamily: 'Inter',
      fantasyFamily: 'Inter',
      monospaceFamily: 'Inter',
    },
  });
  return resvg.render().asPng();
}

function pngResponse(pngBytes, immutable) {
  return new Response(pngBytes, {
    headers: {
      'Content-Type': 'image/png',
      'Cache-Control': immutable ? 'public, max-age=31536000, immutable' : 'public, max-age=86400',
      'Access-Control-Allow-Origin': '*',
    },
  });
}

function jsonResponse(payload, status = 200) {
  return new Response(JSON.stringify(payload), {
    status,
    headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' },
  });
}

export default async function (request) {
  try {
    const requestUrl = new URL(request.url);
    // Canonical public execution route (stable host for email <img> src), not the
    // internal *.insforge.deno.net origin the runtime sees on request.url.
    const selfUrl = `${PROJECT_BASE}/functions/flint-render`;

    if (request.method === 'OPTIONS') {
      return new Response(null, {
        headers: {
          'Access-Control-Allow-Origin': '*',
          'Access-Control-Allow-Methods': 'GET,POST,OPTIONS',
          'Access-Control-Allow-Headers': 'Content-Type,Authorization',
        },
      });
    }

    if (request.method === 'POST') {
      const body = await request.json();
      // Three accepted request shapes: nested {input}, flat tool-param
      // {chartType, encodings, rows, ...}, or a bare ChartAssemblyInput.
      let rawChartInput;
      if (body?.input) {
        rawChartInput = body.input;
      } else if (body?.chartType || body?.encodings || body?.rows) {
        rawChartInput = assembleFlatBody(body);
      } else {
        rawChartInput = body;
      }
      const chartTitle = body?.title ?? null;
      if (!rawChartInput?.data?.values || !rawChartInput?.chart_spec) {
        return jsonResponse({ error: 'Missing input.data.values or input.chart_spec' }, 400);
      }
      // Store the normalized spec so already-clean rows stay the norm going forward;
      // the GET path re-normalizes too, so pre-existing bad rows still render.
      const chartInput = normalizeChartInput(rawChartInput);
      const rows = await runSql(
        'INSERT INTO flint_charts (title, input) VALUES ($1, $2::jsonb) RETURNING id',
        [chartTitle, JSON.stringify(chartInput)],
      );
      const chartId = rows[0].id;
      return jsonResponse({ id: chartId, url: `${selfUrl}?id=${chartId}` });
    }

    if (request.method === 'GET') {
      const chartId = requestUrl.searchParams.get('id');
      const specParam = requestUrl.searchParams.get('spec');
      let chartInput;
      if (chartId) {
        const rows = await runSql('SELECT input FROM flint_charts WHERE id = $1', [chartId]);
        if (!rows.length) return jsonResponse({ error: 'not found' }, 404);
        chartInput = rows[0].input;
      } else if (specParam) {
        chartInput = decodeSpecParam(specParam);
      } else {
        return jsonResponse({ error: 'Provide ?id=<uuid> or ?spec=<base64url-json>' }, 400);
      }
      await ensureWasmReady();
      const pngBytes = renderChartPng(chartInput);
      return pngResponse(pngBytes, Boolean(chartId));
    }

    return jsonResponse({ error: 'Method not allowed' }, 405);
  } catch (error) {
    return jsonResponse({ error: String(error?.message ?? error) }, 500);
  }
}
